package main

const indexHTML = `<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Металлист · кабинет</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f1eb;color:#20221f;font:15px/1.5 system-ui,sans-serif}header{background:#172824;color:white;padding:18px 4vw;display:flex;justify-content:space-between;align-items:center}h1{font-size:24px;margin:0;letter-spacing:-.04em}h2{font-size:20px;margin:0 0 16px}nav{display:flex;gap:8px;flex-wrap:wrap;background:#e2e6dd;padding:12px 4vw}button{border:0;border-radius:5px;background:#214b40;color:white;padding:9px 14px;cursor:pointer}button.secondary{background:#d5ded5;color:#17342b}button:hover{filter:brightness(1.13)}main{max-width:1200px;margin:28px auto;padding:0 20px}.panel{background:white;border:1px solid #dadcd3;border-radius:8px;padding:22px;margin-bottom:16px;overflow:auto}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(185px,1fr));gap:12px}.metric{padding:15px;background:#e9ede6;border-radius:5px}.metric strong{display:block;font-size:23px}label{display:block;font-size:13px;color:#59625b;margin:8px 0 4px}input,select,textarea{width:100%;padding:10px;border:1px solid #aeb7ad;border-radius:5px;background:white;font:inherit}form{max-width:620px}form button{margin-top:15px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;padding:9px;border-bottom:1px solid #e2e6df}th{color:#657168}pre{white-space:pre-wrap;word-break:break-word}.error{color:#a42020}.hint{color:#68746d}.hidden{display:none}#notice{position:fixed;right:16px;bottom:16px;background:#193d32;color:white;padding:12px 16px;border-radius:5px;max-width:420px;display:none}.danger{background:#9a3730} .row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}small{color:#718075}</style>
<header><h1>МЕТАЛЛИСТ / ПЛАТФОРМА</h1><span id="who"></span></header><nav id="nav" class="hidden"><button data-page="dashboard">Обзор</button><button data-page="catalog">Справочники</button><button data-page="registry">Реестры</button><button data-page="operations">Операции</button><button data-page="reports">Отчёты</button><button data-page="audit">Аудит</button><button data-page="account">Пароль</button><button id="logoutButton" class="secondary">Выйти</button></nav><main><section id="login"><div class="panel"><h2>Личный кабинет</h2><form id="loginForm"><label>Логин<input name="login" autocomplete="username" required></label><label>Пароль<input name="password" type="password" autocomplete="current-password" required></label><button>Войти</button></form></div></section><section id="content" class="hidden"></section></main><div id="notice"></div>
<script src="/assets/app.js" defer></script></html>`

const appJS = `
let user=null,page='dashboard',catalog={},registries=[],drafts=[];const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,body,form=false){let opt={credentials:'same-origin',headers:{'X-CSRF':'1'}};if(body!==undefined){opt.method='POST';if(form)opt.body=body;else{opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(body)}}let r=await fetch(path,opt),v=await r.json();if(!r.ok)throw Error(v.error||'Ошибка');return v}
function notify(t,error=false){let n=$('#notice');n.textContent=t;n.style.background=error?'#9a3730':'#193d32';n.style.display='block';setTimeout(()=>n.style.display='none',5000)}
function data(form){return Object.fromEntries(new FormData(form).entries())}
async function start(){try{user=await api('/api/me');$('#login').classList.add('hidden');$('#content').classList.remove('hidden');$('#nav').classList.remove('hidden');$('#who').textContent=user.Name+' · '+user.Role;if(user.Role==='operator'&&page==='dashboard')page='operations';document.querySelectorAll('[data-page=dashboard],[data-page=reports],[data-page=audit]').forEach(x=>x.style.display=user.Role==='operator'?'none':'');await show(page)}catch{}}
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{user=await api('/login',data(e.target));await start()}catch(x){notify(x.message,true)}};
async function logout(){await api('/logout',{});location.reload()}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>show(b.dataset.page));
$('#logoutButton').onclick=logout;
async function show(p){page=p;try{if(p==='dashboard')await dashboard();if(p==='catalog')await catalogPage();if(p==='registry')await registryPage();if(p==='operations')await operationsPage();if(p==='reports')await reportsPage();if(p==='audit')await auditPage();if(p==='account')await accountPage()}catch(e){notify(e.message,true)}}
const money=v=>esc(v)+' ₽';const opts=(arr,label='name')=>(arr||[]).map(x=>'<option value="'+esc(x.id)+'">'+esc(x[label])+'</option>').join('');
async function dashboard(){let r=await api('/api/report');$('#content').innerHTML='<div class="panel"><h2>Финансовая позиция</h2><div class="grid">'+Object.entries(r.summary).map(([k,v])=>'<div class="metric"><small>'+esc(k)+'</small><strong>'+money(v)+'</strong></div>').join('')+'</div><p class="hint">Суммы рассчитаны из подтверждённых проводок. Исходные реестры и наблюдения остатков учитываются отдельно.</p></div><div class="panel"><h2>Расхождения при передаче</h2>'+table(r.handover_differences)+'</div><div class="panel"><h2>Наблюдаемые остатки и расхождения</h2>'+table(r.observations)+'</div><div class="panel"><h2>Остатки по счетам и ответственным</h2>'+table(r.balances)+'</div>'}
function table(arr){if(!arr?.length)return '<p class="hint">Пока нет записей</p>';let cols=Object.keys(arr[0]);return '<table><thead><tr>'+cols.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+arr.map(x=>'<tr>'+cols.map(k=>'<td>'+esc(typeof x[k]==='object'?JSON.stringify(x[k]):x[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
async function catalogPage(){catalog=await api('/api/catalog');$('#content').innerHTML='<div class="panel"><h2>Новая запись</h2><form id="catForm"><label>Тип<select name="kind" id="catKind"><option value="merchant">Мерчант</option><option value="bank">Банк</option><option value="card">Карта</option><option value="custodian">Хранитель</option><option value="user">Пользователь (только системный администратор)</option></select></label><label>Код / логин<input name="code"></label><label>Имя / название<input name="name" required></label><label>Банк<select name="bank_id">'+opts(catalog.banks)+'</select></label><label>Маска карты<input name="mask" placeholder="000000******1234"></label><label>Метка владельца карты, только вымышленные данные<input name="owner_label"></label><label>Тип хранителя<select name="custodian_kind"><option value="collector">Сборщик</option><option value="operator">Операционист</option></select></label><label>Роль пользователя<select name="role"><option value="operator">Операционист</option><option value="accountant">Бухгалтер</option><option value="auditor">Аудитор</option></select></label><button>Создать</button></form></div><div class="panel"><h2>Связать Telegram ID (системный администратор)</h2><form id="telegramLink"><label>Пользователь<select name="user_id">'+opts(catalog.users)+'</select></label><label>Числовой Telegram ID<input name="telegram_id" required></label><button>Связать</button></form></div><div class="panel"><h2>Назначить карту операционисту</h2><form id="assignCard"><label>Операционист<select name="user_id">'+opts((catalog.users||[]).filter(x=>x.role==='operator'))+'</select></label><label>Карта<select name="card_id">'+opts(catalog.cards,'mask')+'</select></label><button>Назначить</button></form></div>'+Object.entries(catalog).map(([k,v])=>'<div class="panel"><h2>'+esc(k)+'</h2>'+table(v)+'</div>').join('');$('#assignCard').onsubmit=async e=>{e.preventDefault();try{await api('/api/card/assign',data(e.target));notify('Карта назначена')}catch(ex){notify(ex.message,true)}};$('#telegramLink').onsubmit=async e=>{e.preventDefault();try{await api('/api/user/telegram',data(e.target));notify('Telegram ID связан')}catch(ex){notify(ex.message,true)}};$('#catForm').onsubmit=async e=>{e.preventDefault();let m=data(e.target);m.login=m.code;try{let x=await api('/api/catalog/create',m);notify('Создано '+x.id+(x.temporary_password?' · одноразовый пароль: '+x.temporary_password:''));await catalogPage()}catch(ex){notify(ex.message,true)}}}
async function registryPage(){catalog=await api('/api/catalog');registries=await api('/api/registries');$('#content').innerHTML='<div class="panel"><h2>Загрузить реестр</h2><p><a href="/api/demo/sample">Скачать синтетический XLSX для проверки</a> · <a href="/api/demo/sample?kind=csv">Скачать банковский CSV</a></p><form id="uploadForm"><label>Мерчант<select name="merchant_id">'+opts(catalog.merchants)+'</select></label><label>Внешний номер реестра<input name="external_ref" required></label><label>XLSX или банковский CSV<input name="file" type="file" accept=".xlsx,.csv" required></label><button>Загрузить и проверить</button></form><p class="hint">Файл сохраняется как источник. Только полностью валидный реестр может быть подтверждён. Банковский сбор показан отдельно и не попадает в прибыль.</p></div><div class="panel"><h2>Реестры</h2>'+table(registries)+'</div><div class="panel"><h2>Подтвердить реестр</h2><form id="regConfirm"><label>Реестр<select name="id" id="regSelect">'+opts(registries,'external_ref')+'</select></label><div id="regPreview"></div><div id="regRows"></div><label>Точная сумма пополнения<input name="confirm_total" required></label><label>Точная комиссия<input name="confirm_commission" required></label><button>Подтвердить поступление и проводки</button></form></div><div class="panel"><h2>Разовая ставка для загруженного реестра</h2><form id="manualForm"><label>Реестр<select name="id">'+opts(registries,'external_ref')+'</select></label><label>Ставка в сотых долях процента (4,50% = 450)<input name="rate_bp" required></label><label>Основание<input name="reason" required></label><button>Утвердить ставку и обновить preview</button></form></div><div class="panel"><h2>Сторно реестра</h2><form id="reverseForm"><label>Реестр<select name="id">'+opts(registries,'external_ref')+'</select></label><label>Причина<input name="reason" required></label><button class="danger">Сторнировать в пределах 72 часов</button></form></div><div class="panel"><h2>Исправить разовую ставку проведённого реестра</h2><form id="manualCorrectionForm"><label>Реестр<select name="registry_id">'+opts(registries,'external_ref')+'</select></label><label>Новая ставка в сотых долях процента<input name="rate_bp" required></label><label>Основание исправления<input name="reason" required></label><button>Показать изменение баланса</button></form><pre id="manualCorrectionPreview"></pre><button id="manualCorrectionConfirm" class="hidden">Подтвердить исправление</button></div><div class="panel"><h2>Тариф задним числом</h2><form id="tariffForm"><label>Мерчант<select name="merchant_id">'+opts(catalog.merchants)+'</select></label><label>Ставка в сотых долях процента<input name="rate_bp" required></label><label>С даты по Москве<input name="valid_from" type="date" required></label><button>Показать пересчёт</button></form><pre id="tariffPreview"></pre><button id="tariffConfirm" class="hidden">Подтвердить пересчёт и баланс после него</button></div>';
$('#uploadForm').onsubmit=async e=>{e.preventDefault();try{let x=await api('/api/registry/upload',new FormData(e.target),true);notify('Загружено '+x.id);await registryPage()}catch(ex){notify(ex.message,true)}};
async function regView(){let x=registries.find(x=>x.id===$('#regSelect').value);$('#regPreview').textContent=x?'Общая сумма '+x.total+' ₽; ставка '+(x.rate_bp/100).toFixed(2)+'%; комиссия '+x.commission+' ₽; к возврату '+x.net+' ₽; версия '+x.version:'';if(x){$('#regRows').innerHTML=table(await api('/api/registry/rows?id='+encodeURIComponent(x.id)));$('#regConfirm [name=confirm_total]').value=x.total;$('#regConfirm [name=confirm_commission]').value=x.commission}}$('#regSelect').onchange=regView;regView();
$('#regConfirm').onsubmit=async e=>{e.preventDefault();let m=data(e.target),x=registries.find(x=>x.id===m.id);m.version=String(x.version);m.confirm_rate_bp=String(x.rate_bp);try{await api('/api/registry/confirm',m);notify('Реестр подтверждён');await registryPage()}catch(ex){notify(ex.message,true)}};
$('#manualForm').onsubmit=async e=>{e.preventDefault();let m=data(e.target),x=registries.find(x=>x.id===m.id);m.version=String(x.version);try{await api('/api/registry/manual-rate',m);notify('Ставка утверждена');await registryPage()}catch(ex){notify(ex.message,true)}};
$('#reverseForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/registry/reverse',data(e.target));notify('Реестр сторнирован');await registryPage()}catch(ex){notify(ex.message,true)}};
let manualCorrection=null;$('#manualCorrectionForm').onsubmit=async e=>{e.preventDefault();try{manualCorrection=await api('/api/manual/preview',data(e.target));$('#manualCorrectionPreview').textContent=JSON.stringify(manualCorrection,null,2);$('#manualCorrectionConfirm').classList.remove('hidden')}catch(ex){notify(ex.message,true)}};$('#manualCorrectionConfirm').onclick=async()=>{try{await api('/api/manual/confirm',{registry_id:manualCorrection.registry_id,rate_bp:String(manualCorrection.rate_bp),reason:manualCorrection.reason,preview_hash:manualCorrection.preview_hash});notify('Ставка исправлена');await registryPage()}catch(ex){notify(ex.message,true)}};let preview=null;$('#tariffForm').onsubmit=async e=>{e.preventDefault();try{preview=await api('/api/tariff/preview',data(e.target));$('#tariffPreview').textContent=JSON.stringify(preview,null,2);$('#tariffConfirm').classList.remove('hidden')}catch(ex){notify(ex.message,true)}};$('#tariffConfirm').onclick=async()=>{try{await api('/api/tariff/confirm',{merchant_id:preview.merchant_id,rate_bp:String(preview.rate_bp),valid_from:preview.valid_from,preview_hash:preview.preview_hash});notify('Тариф и корректировки подтверждены');await registryPage()}catch(ex){notify(ex.message,true)}}}
const fields={withdrawal:['card_id','custodian_id'],handover:['from_custodian_id','to_custodian_id'],repayment:['merchant_id','source_kind','source_id'],expense:['source_kind','source_id','category'],injection:['person_id','destination_kind','destination_id'],shortage:['custodian_id'],writeoff:['custodian_id','shortage_id'],surplus:['custodian_id'],surplus_income:['source_ref'],surplus_merchant:['source_ref','merchant_id'],surplus_shortage:['source_ref','custodian_id','shortage_id'],surplus_return:['source_ref','merchant_id','source_kind','source_id'],collection:['receivable_account','merchant_id','custodian_id','shortage_id','destination_kind','destination_id'],recovery:['writeoff_id','destination_kind','destination_id'],forgive_injection:['person_id']};
function field(k){if(k==='card_id')return '<label>Карта<select name="'+k+'">'+opts(catalog.cards,'mask')+'</select></label>';if(k==='merchant_id')return '<label>Мерчант<select name="'+k+'">'+opts(catalog.merchants)+'</select></label>';if(k.endsWith('custodian_id')||k==='person_id')return '<label>'+k+'<select name="'+k+'">'+opts(catalog.custodians)+'</select></label>';if(k.endsWith('_kind'))return '<label>'+k+'<select name="'+k+'"><option value="cash">Наличные</option><option value="card">Карта</option></select></label>';return '<label>'+k+'<input name="'+k+'" required></label>'}
async function operationsPage(){catalog=await api('/api/catalog');drafts=await api('/api/drafts');$('#content').innerHTML='<div class="panel"><h2>Создать черновик</h2><form id="opForm"><label>Тип операции<select name="kind" id="opKind">'+Object.keys(fields).map(k=>'<option value="'+k+'">'+k+'</option>').join('')+'</select></label><div id="opFields"></div><label id="amountLabel">Сумма в рублях<input name="amount" required placeholder="1000.00"></label><label>Основание / комментарий<input name="reason"></label><button>Сохранить черновик</button></form><p class="hint">Главный администратор отдельно подтверждает точную сумму. Черновик не меняет остатки.</p></div><div class="panel"><h2>Черновики и операции</h2>'+table(drafts)+'</div><div class="panel"><h2>Подтверждение</h2><form id="opConfirm"><label>Черновик<select name="id">'+opts(drafts,'kind')+'</select></label><label>Версия<input name="version" value="1" required></label><label>Точная сумма<input name="confirm_amount" placeholder="1000.00" required></label><button>Подтвердить списание / изменение</button></form></div><div class="panel"><h2>Сторно операции</h2><form id="opReverse"><label>Операция<select name="id">'+opts(drafts,'kind')+'</select></label><label>Причина<input name="reason" required></label><button class="danger">Сторнировать</button></form></div><div class="panel"><h2>Наблюдаемый остаток карты</h2><form id="obForm"><label>Карта<select name="card_id">'+opts(catalog.cards,'mask')+'</select></label><label>Остаток в рублях<input name="amount" required></label><button>Сохранить наблюдение</button></form></div>';
function renderFields(){$('#opFields').innerHTML=fields[$('#opKind').value].map(field).join('');$('#amountLabel').firstChild.textContent=$('#opKind').value==='handover'?'Заявленная сумма в рублях':'Сумма в рублях'}$('#opKind').onchange=renderFields;renderFields();$('#opForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/draft',data(e.target));notify('Черновик создан');await operationsPage()}catch(ex){notify(ex.message,true)}};$('#opConfirm').onsubmit=async e=>{e.preventDefault();try{await api('/api/draft/confirm',data(e.target));notify('Операция проведена');await operationsPage()}catch(ex){notify(ex.message,true)}};$('#opReverse').onsubmit=async e=>{e.preventDefault();try{await api('/api/draft/reverse',data(e.target));notify('Операция сторнирована');await operationsPage()}catch(ex){notify(ex.message,true)}};$('#obForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/observation',data(e.target));notify('Наблюдение сохранено')}catch(ex){notify(ex.message,true)}}}
async function reportsPage(){let r=await api('/api/report');$('#content').innerHTML='<div class="panel"><h2>Баланс, долг, выручка и прибыль</h2><div class="grid">'+Object.entries(r.summary).map(([k,v])=>'<div class="metric"><small>'+esc(k)+'</small><strong>'+money(v)+'</strong></div>').join('')+'</div></div><div class="panel"><h2>Помесячный P&L</h2><form id="monthForm"><label>Месяц<input type="month" name="month" required></label><button>Показать</button></form><pre id="monthView"></pre><button id="approveMonth" class="hidden">Утвердить текущую версию (бухгалтер)</button></div><div class="panel"><h2>Cashflow по датам и событиям</h2>'+table(r.cashflow)+'</div><div class="panel"><h2>Остатки счетов</h2>'+table(r.balances)+'</div>';let current=null;$('#monthForm').onsubmit=async e=>{e.preventDefault();current=(await api('/api/report?month='+data(e.target).month)).month;$('#monthView').textContent=JSON.stringify(current,null,2);$('#approveMonth').classList.remove('hidden')};$('#approveMonth').onclick=async()=>{try{await api('/api/report/approve',{month:current.month,digest:current.digest});notify('Отчёт утверждён')}catch(ex){notify(ex.message,true)}}}
async function accountPage(){$('#content').innerHTML='<div class="panel"><h2>Сменить одноразовый пароль</h2><form id="passwordForm"><label>Текущий пароль<input name="current" type="password" required></label><label>Новый пароль, не короче 16 символов<input name="new" type="password" minlength="16" required></label><button>Сменить и завершить все сеансы</button></form></div>';$('#passwordForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/password',data(e.target));notify('Пароль изменён. Войдите заново.');location.reload()}catch(ex){notify(ex.message,true)}}}
async function auditPage(){let r=await api('/api/audit');$('#content').innerHTML='<div class="panel"><h2>Аудит действий</h2>'+table(r)+'</div>'}
start();`
